void obstacleinc (void){

cloudx--;
if (cloudx==-128) cloudx = 127;

objects[random].x--;

if(objects[random].x==-40) {
  random = Random(3);
  objects[random].x=128;
}

if(obsani == 0){
  obsani = 1;
} else {
  obsani = 0;
}

if(idle==0){
 idle = 1;
 yerraballi.currentbm = yerraballi.idle[idle];
} else{
 idle = 0;
 yerraballi.currentbm = yerraballi.idle[idle];
}


if(jumpflag){

if(jumpup<50){
jumpup++;
yerraballi.y--;
yerraballi.currentbm = yerraballi.jump[0];
}

if(jumpup==50 && inair<15 ){
yerraballi.currentbm = yerraballi.jump[1];
inair++;
} else if(jumpdown>=1 && inair==15){
jumpdown--;
yerraballi.y++;
yerraballi.currentbm = yerraballi.jump[2];
} else if(jumpdown==0 && jumpup==50){
jumpdown = 49;
jumpup = 1;
inair=0;
jumpflag = false;
yerraballi.currentbm = yerraballi.idle[idle];
}
}


if(duckflag){

 if(duck<60){
  yerraballi.h=32;
  yerraballi.currentbm = yerraballi.duck;
  duck++;
 } else{
  yerraballi.h=36;
  yerraballi.currentbm = yerraballi.idle[idle];
  duck=0;
  duckflag = false;
 }
}

  if(random==1){

  if(objects[random].x==45){

    if (duckflag){

    if((yerraballi.y-yerraballi.h) < (objects[random].y)){
      startflag = 2;
      collision = true;
      Sound_gruntsound();
    }
   }

   if(!duckflag){
      startflag = 2;
      collision = true;
      Sound_gruntsound();
   }

  }
  }

  if(random!=1){
   if(objects[random].x==52){
   
   if(!jumpflag) {
    collision=true;
    startflag=2;
    Sound_gruntsound();
   }

   if(jumpflag){

    if(yerraballi.y < (objects[random].y - objects[random].h)){
      startflag=2;
      collision=true;
      Sound_gruntsound();
    }
   }  

   }

   }
}

void score (void){

 countt++;
 if(countt==100){
 countt=0;
 second++;
 }
 if(second==60){
  second = 0;
  printfinal = true;
 }
 }




void TIMG0_IRQHandler(void){

  if((TIMG0->CPU_INT.IIDX) == 1){ // this will acknowledge
    if(startflag==1){
    (*PeriodicTask0)();                // execute user task
    }
  }
}

void TIMG12_IRQHandler(void){

if((TIMG12->CPU_INT.IIDX) == 1){ // this will acknowledge
 
  if(startflag==0){
   if(Switch_In()==1){
    startflag = 1;
    random = Random(4);
   }

   SPdata = ADCin();
  }

  if(startflag==1){
   
   if(Switch_In()==8 && !duckflag){
   jumpflag=true;
   Sound_jump();

}
   if(Switch_In()==2 && !jumpflag){
   duckflag=true;
   Sound_swosh();
}
    (*PeriodicTask12)(); // execute user task
  }


  if (startflag == 2){
   if(Switch_In()==4){
    startflag = 0;
    timedone=false;
    collision=false;
    countt = 0;
    second = 0;
    printfinal = false;
    jumpup = 1;
    jumpdown = 49;
    duck = 0;
    jumpflag = false;
    duckflag = false;
    inair = 0;
    eerx = 120;
   }

  

  }

  }                
}



uint8_t TExaS_LaunchPadLogicPB27PB26(void){
  return (0x80|((GPIOB->DOUT31_0>>26)&0x03));
}


